      `PERSON_ADDED sheet=${sheet} by=uma name=Ada grade=A`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=entry-date value=2026-03-05`,
      `PERIOD_ADDED sheet=${sheet} by=uma period=P1 from=2026-02-01 to=2026-02-10`,
      `TEMPLATE_SAVED sheet=${sheet} by=uma name=Fee amount=12.50 note=fee`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=12.50 date=2026-03-05`,
      `TEMPLATE_SAVED sheet=${sheet} by=uma name=Fee amount=20.00 note=fee2`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=20.00 date=2026-03-05`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=entry-date value=2026-02-05`,
      `PERIOD_CLOSED sheet=${sheet} by=uma period=P1 total=0.00`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=20.00 date=2026-02-05`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=entry-date value=`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=20.00 date=2026-03-10`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ada amount=12.50 date=2026-03-05 number=1`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=12.50 due-total=1.25 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=12.50 due-total=1.25 overdue-total=0.00`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ada amount=20.00 date=2026-03-05 number=2`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=32.50 due-total=3.25 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=32.50 due-total=3.25 overdue-total=0.00`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ada amount=20.00 date=2026-02-05 number=3`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=52.50 due-total=5.25 overdue-total=2.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=52.50 due-total=5.25 overdue-total=2.00`
    ]);
  });
  test("claim templates scenario 1", { tag: '@functionality' }, async ({ browser }) => {
