            return history.asOf(sheetId, asOf).claims().values().stream()
                    .map(Claim::getTags)
                    .filter(Objects::nonNull)
                    .flatMap(t -> Arrays.stream(t.split(",")))
                    .distinct()
                    .sorted()
                    .toList();
