import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/quick-add")
@Validated
public class QuickAddController {

    /** The quick-add bar's values: a person's name (as the person form takes it) and a claim's
     *  amount (as the claim form takes it). */
    public record QuickAddForm(
            @NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "\\d{1,13}(\\.\\d{1,2})?") String amount) {
    }

    /** The person as they now show (added when personAdded) and the claim just added. */
    public record QuickAddView(PersonView person, boolean personAdded, ClaimView claim) {
    }

    private final QuickAddService service;
    private final PersonService people;
    private final ClaimService claims;

    public QuickAddController(QuickAddService service, PersonService people, ClaimService claims) {
        this.service = service;
        this.people = people;
        this.claims = claims;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public QuickAddView add(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody QuickAddForm body) {
        QuickAddService.QuickAdd q = service.add(sheetId, user.trim(), body.name(), new BigDecimal(body.amount()));
        return new QuickAddView(PersonView.of(q.person(), people.today(sheetId), people.statementSummary(q.person().getId()),
                people.patronIds(q.person().getId()), people.isWatching(q.person().getId(), user.trim())),
                q.personAdded(), ClaimView.of(q.claim(), claims.logOf(q.claim().getId()), claims.commentsOf(q.claim().getId())));
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class QuickAddService {

    /** The grade a person the quick-add creates is given. */
    static final String NEW_PERSON_GRADE = "A";

    /** A quick-add's result: the person the claim is for (perhaps just created) and the claim. */
    public record QuickAdd(Person person, boolean personAdded, Claim claim) {
    }

    private final PersonRepository people;
    private final PersonService personService;
    private final ClaimService claimService;

    public QuickAddService(PersonRepository people, PersonService personService, ClaimService claimService) {
        this.people = people;
        this.personService = personService;
        this.claimService = claimService;
    }

    /** Add a DRAFT claim dated the sheet's entry date (while set, else its today) with an empty note for the person with this name
     *  or alias (ignoring case and surrounding spaces), adding them with grade A first when the sheet has no
     *  such person. One change: when the claim is refused, the person is not added either. */
    @Transactional
    public QuickAdd add(String sheetId, String user, String name, BigDecimal amount) {
        String trimmed = name.trim();
        Person person = people.findBySheetIdAndNameOrAlias(sheetId, trimmed).orElse(null);
        boolean added = person == null;
        if (added) {
            person = personService.add(sheetId, user, trimmed, NEW_PERSON_GRADE, null, null);
        }
        Claim claim = claimService.add(sheetId, user, person.getId(), amount, null, "", null, null, null);
        return new QuickAdd(person, added, claim);
    }
}

