  'Enter a clerk limit of 0.00 or more with up to two decimals (blank: no limit) and a floor of 0.00 or more with up to two decimals (blank: 1.00) and terms of a whole number of business days (blank: 14) and terms for each grade of a whole number of business days (blank: the sheet\'s terms) and grace days for each grade of a whole number of days (blank: none) and a late percent of 0.00 or more with up to two decimals (blank: 0.00) and a policy date as yyyy-mm-dd (blank: the sheet\'s today) and a period numbering from-date as yyyy-mm-dd (blank: off) and an entry date as yyyy-mm-dd (blank: off) and a cap of 0.00 or more with up to two decimals (blank: none) and a proof threshold of 0.00 or more with up to two decimals (blank: none) and grace days of a whole number of days (blank: off) and the roles for each action as clerk and/or steward, comma separated (blank: the standing rule), each from-date as yyyy-mm-dd (blank: the sheet\'s today).';

export function settingsError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 400) return SETTINGS_INVALID;
  return otherError(e);
}

export function roleError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 400) return 'Enter a user name without spaces and a role of clerk, steward or viewer.';
  if (e instanceof HttpErrorResponse && e.status === 409) return 'The role was changed at the same moment; try again.';
  return otherError(e);
}

export function delegateError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 400) return 'Enter a user name without spaces and a to-date on or after the from-date, each as yyyy-mm-dd.';
  if (e instanceof HttpErrorResponse && e.status === 403) return 'Only a steward can delegate the steward role.';
  return otherError(e);
}

export function voidReasonError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 400) return 'Enter a void reason.';
  if (e instanceof HttpErrorResponse && e.status === 409) return 'That reason is on the list already.';
  return otherError(e);
}

export function holidayError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 400) return 'Enter a holiday as yyyy-mm-dd.';
  if (e instanceof HttpErrorResponse && e.status === 409) return 'That date is a holiday already.';
  return otherError(e);
}

